<template>
  <main class="app-container pc-page">
    <h1>模型与设置</h1><p class="pc-muted">选择模型和个人偏好。扩展能力按需配置，编码入口无需登记目录或成员。</p>
    <div class="pc-toolbar"><el-button :loading="loading" @click="reload">刷新配置</el-button><el-button @click="advanced = !advanced">{{ advanced ? '收起高级能力' : '高级能力' }}</el-button></div>
    <el-alert v-if="contextError || pageError || error" :title="contextError || pageError || error" type="error" :closable="false" /><OperationTask :task-id="operationTaskId" :directory-context-id="directoryContextId" :title="operationTitle" @settled="operationSettled" />
    <section class="pc-panel"><h2>默认模型</h2><div class="pc-toolbar"><el-select v-model="defaultModelId" aria-label="选择个人默认模型"><el-option v-for="model in models" :key="model.id" :value="model.id" :label="`${model.platformModel ? '内置 · ' : '个人 · '}${model.displayName || model.modelId}`" :disabled="!model.enabled" /></el-select><el-button v-hasPermi="['paicli:connection:manage']" type="primary" :loading="busy" :disabled="!defaultModelId" @click="saveDefaultModel">设为我的默认模型</el-button></div><p class="pc-muted">内置模型由管理员发布；个人模型和偏好只影响本人，新对话使用默认模型。</p></section><EmbeddingCapability :settings="personal.context.value?.settings" :owner-user-id="personal.context.value?.ownerUserId || ''" :capability="personal.context.value?.embedding" :releases="personal.context.value?.embeddingReleases || []" :advanced="advanced" @saved="reload" @task="trackTask" /><el-tabs v-model="tab"><el-tab-pane v-if="advanced && checkPermi(['paicli:connection:manage'])" label="高级检索配置" name="knowledge"><PersonalKnowledgeConfig :settings="personal.context.value?.settings" :owner-user-id="personal.context.value?.ownerUserId || ''" @saved="reload" /></el-tab-pane>
      <el-tab-pane label="供应商与模型" name="models"><el-button v-hasPermi="['paicli:connection:manage']" @click="editProvider()">登记供应商</el-button><el-alert title="完整供应商与模型列表来自中心登记；模型刷新只追加，失败保留原配置。未知模型默认 128k 文本，能力须核实；Sub2API 文字、工具与图片分别验证，图片仅在 Responses 的有效证明通过后可用。" type="info" :closable="false" /><el-table :data="providers"><el-table-column prop="name" label="供应商" width="140" /><el-table-column label="协议" width="130"><template #default="{ row }">{{ row.provider === "sub2api" ? wireApiName(row.wireApi) : protocolName(row.protocol) }}</template></el-table-column><el-table-column prop="baseUrl" label="服务地址" min-width="250" /><el-table-column label="密钥状态" width="130"><template #default="{ row }">{{ row.secretConfigured ? '已配置（不回显）' : '未配置' }}</template></el-table-column><el-table-column label="状态"><template #default="{ row }">{{ stateName(row.status) }}<p v-if="row.lastError" class="pc-muted">{{ row.lastError }}</p></template></el-table-column><el-table-column label="操作" width="280"><template #default="{ row }"><el-button v-hasPermi="['paicli:connection:manage']" link @click="editProvider(row)">配置</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || !row.secretConfigured" @click="refreshProvider(row)">刷新模型</el-button></template></el-table-column></el-table><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!providers.length" @click="editModel()">添加模型</el-button></div><el-table :data="models"><el-table-column prop="modelId" label="完整模型 ID" min-width="280" /><el-table-column label="供应商"><template #default="{ row }">{{ row.platformModel ? '平台内置' : providers.find(item => item.id === row.providerId)?.name || row.providerId }}</template></el-table-column><el-table-column prop="contextWindow" label="上下文 Token" width="150" /><el-table-column label="能力" min-width="200"><template #default="{ row }"><p>{{ row.capabilityKnown ? '文字与工具：已核验' : '文字与工具：待验证' }}</p><p>{{ row.supportsImages ? '图片：已核验' : row.imageVerificationFailure ? '图片：验证失败，文字能力保留' : '图片：未验证或不可用' }}</p><p v-if="row.imageVerification?.message" class="pc-muted">{{ row.imageVerification.message }}</p></template></el-table-column><el-table-column label="启用"><template #default="{ row }">{{ row.enabled ? '可选' : '未启用' }}</template></el-table-column><el-table-column label="配置" width="130"><template #default="{ row }"><el-button v-if="!row.platformModel" v-hasPermi="['paicli:connection:manage']" link @click="editModel(row)">能力与预算</el-button><el-tag v-if="row.platformModel" type="info">内置只读</el-tag><el-button v-if="canPublish && !row.platformModel" link :disabled="busy" @click="openPublish(row)">{{row.releaseId ? '重新发布' : '发布内置模型'}}</el-button><el-button v-if="canPublish && row.releaseId && !row.platformModel && row.releaseStatus !== 'REVOKED'" link type="danger" :disabled="busy" @click="revokeRelease(row)">撤销发布</el-button><el-button v-if="!row.platformModel && providers.find(item => item.id === row.providerId)?.provider === 'sub2api'" v-hasPermi="['paicli:connection:manage']" link :disabled="busy" @click="verifyModel(row)">验证文字与工具</el-button><el-button v-if="!row.platformModel && providers.find(item => item.id === row.providerId)?.provider === 'sub2api' && providers.find(item => item.id === row.providerId)?.wireApi === 'responses'" v-hasPermi="['paicli:connection:manage']" link :disabled="busy || !row.capabilityKnown" @click="verifyModel(row,'IMAGES')">验证图片理解</el-button></template></el-table-column></el-table><el-empty v-if="!models.length" description="没有已登记模型，请先配置供应商" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="MCP 服务 / 资源 / 提示词" name="mcp"><el-alert v-if="personal.context.value && !directoryContextId" title="当前个人执行目录尚不可用" :description="directoryReadinessDescription('现有服务列表仍可查看；登记服务需要当前个人目录。')" type="warning" :closable="false" /><el-alert title="项目 MCP 变更需要对当前配置哈希重新批准信任；stdio 属于代码执行，未验证隔离时不能启动。OAuth、sampling、自动恢复尚未承诺。" type="warning" :closable="false" /><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!directoryContextId" @click="editMcp()">登记 MCP 服务</el-button><el-table :data="mcpServers"><el-table-column prop="name" label="服务" /><el-table-column label="来源 / 传输"><template #default="{ row }">{{ row.scope === 'PROJECT' ? '项目' : '当前用户' }} / {{ row.transport }}</template></el-table-column><el-table-column label="状态 / 信任"><template #default="{ row }">{{ stateName(row.status) }}<p class="pc-muted">{{ row.configHash === row.trustedHash ? '当前配置已批准信任' : '需确认当前配置' }}</p><p v-if="row.error">{{ row.error }}</p></template></el-table-column><el-table-column label="操作" min-width="370"><template #default="{ row }"><el-button link @click="viewMcp(row)">工具 / 资源 / 提示</el-button><el-button v-hasPermi="['paicli:connection:manage']" link @click="editMcp(row)">修改配置</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || row.configHash !== row.trustedHash" @click="actMcp(row,'START')">启动</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy" @click="actMcp(row,'STOP')">停止</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy || row.configHash !== row.trustedHash" @click="actMcp(row,'RESTART')">重启</el-button><el-button link @click="mcpLogs(row)">日志</el-button></template></el-table-column></el-table><el-empty v-if="!mcpServers.length" description="没有已登记 MCP 服务" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="浏览器与 CDP" name="browser"><el-alert v-if="personal.context.value && !directoryContextId" title="当前个人执行目录尚不可用" :description="directoryReadinessDescription('当前目录的浏览器配置尚未读取，保存和连接操作暂不可用。')" type="warning" :closable="false" /><section class="pc-panel"><h2>当前浏览器连接</h2><p v-if="browser">{{ browser.connected ? '已连接' : '未连接' }} · {{ browser.mode }} · {{ browser.endpoint }}</p><p v-if="browser" class="pc-muted">最近探活 {{ displayTime(browser.lastProbeAt) }} · 版本 {{ browser.version }}</p><el-alert v-if="browser?.error" :title="browser.error" type="error" :closable="false" /><el-form label-width="130px"><el-form-item label="目标模式"><el-select v-model="browserForm.mode"><el-option label="独立隔离浏览器" value="ISOLATED" /><el-option label="共享登录态（须确认）" value="SHARED" /><el-option label="断开" value="DISCONNECTED" /></el-select></el-form-item><el-form-item v-if="browserForm.mode !== 'DISCONNECTED'" label="受控 MCP 配置"><el-select v-model="browserForm.mcpConfigId" placeholder="同当前目录已信任 chrome-devtools"><el-option v-for="server in mcpServers.filter(item=>item.name === 'chrome-devtools' && item.configHash === item.trustedHash)" :key="server.id" :label="`${server.name} · 版本 ${server.version}`" :value="server.id" /></el-select></el-form-item><el-form-item label="CDP 地址"><el-input v-model="browserForm.endpoint" placeholder="显式登记的本机 CDP 端点" /></el-form-item><el-form-item v-if="browserForm.mode === 'SHARED'" label="登录态影响"><el-checkbox v-model="browserForm.confirmShared">已确认连接常用浏览器；敏感写入仍须逐次批准</el-checkbox></el-form-item></el-form><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :loading="busy" :disabled="!browser?.id" @click="probe">探活当前连接</el-button><el-button v-hasPermi="['paicli:connection:manage']" type="primary" :loading="busy" :disabled="!browser || (browserForm.mode === 'SHARED' && !browserForm.confirmShared)" @click="saveBrowser">保存目标连接配置</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('CONNECT')">连接已登记目标</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('TABS')">查询实际标签页</el-button><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!browser?.id" :loading="busy" @click="actBrowser('DISCONNECT')">断开当前连接</el-button></div><p class="pc-muted">保存配置后须连接或探活，中心回执才表示成功；isolated 不加载用户常用 profile，shared 登录态不能绕审批。</p><p v-if="browser?.tabsStatus" class="pc-muted">标签页回执：{{stateName(browser.tabsStatus)}}</p><el-empty v-if="browser?.tabs && !browser.tabs.length" description="执行环境 已确认当前没有标签页" /><el-alert v-if="browser && !browser.tabs" title="尚无可解析的标签页列表，请查询实际标签页并核对任务回执。" type="info" :closable="false" /><el-collapse v-if="browser?.tabsResult"><el-collapse-item title="最近标签页原始回执"><pre class="pc-pre">{{safeText(browser.tabsResult)}}</pre></el-collapse-item></el-collapse><el-table v-if="browser?.tabs?.length" :data="browser.tabs"><el-table-column prop="id" label="标签页 ID" /><el-table-column prop="title" label="实际标题" /><el-table-column prop="url" label="实际地址" min-width="260" /></el-table></section></el-tab-pane>
      <el-tab-pane v-if="advanced" label="Skills" name="skills"><el-alert v-if="personal.context.value && !directoryContextId" title="当前个人执行目录尚不可用" :description="directoryReadinessDescription('当前目录的Skills配置尚未读取，重载操作暂不可用。')" type="warning" :closable="false" /><el-alert title="builtin → user → project 同名覆盖，只展示实际生效版本；Skill 内容不能扩大权限。索引和正文均由 执行环境 校验。" type="info" :closable="false" /><el-button v-hasPermi="['paicli:connection:manage']" :disabled="!directoryContextId" :loading="busy" @click="reloadSkillList">重载 Skills</el-button><el-table :data="skills"><el-table-column prop="name" label="Skill" /><el-table-column prop="description" label="描述" min-width="230" /><el-table-column prop="scope" label="来源" width="120" /><el-table-column label="状态" width="180"><template #default="{ row }">{{ row.enabled ? '已启用' : '已停用' }} · {{ row.effective ? '生效版本' : '已被覆盖' }}</template></el-table-column><el-table-column label="操作" width="180"><template #default="{ row }"><el-button link @click="showSkill(row.id)">查看正文</el-button><el-button v-hasPermi="['paicli:connection:manage']" link :disabled="busy" @click="toggleSkill(row)">{{ row.enabled ? '停用' : '启用' }}</el-button></template></el-table-column></el-table><el-empty v-if="!skills.length" description="未加载可用 Skills" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="微信 iLink 文本" name="wechat"><el-alert v-if="personal.context.value && !directoryContextId" title="当前个人执行目录尚不可用" :description="directoryReadinessDescription('当前目录的微信配置尚未读取，当前画面不能判断账号绑定或在线状态。')" type="warning" :closable="false" /><el-alert title="微信仅提供文本通道。必须绑定若依用户与唯一当前目录；没有审批面板的未知写入默认拒绝，二维码登录不等于已有任务授权。" type="warning" :closable="false" /><section class="pc-panel"><el-descriptions v-if="wechat" :column="1" border><el-descriptions-item label="状态">{{ stateName(wechat.status) }}</el-descriptions-item><el-descriptions-item label="若依身份 / sender">{{ wechat.boundUserName || '未绑定' }} / {{ wechat.senderMasked || '未绑定' }}</el-descriptions-item><el-descriptions-item label="日预算">{{ wechat.dailyUsed }} / {{ wechat.dailyBudget }} Token</el-descriptions-item><el-descriptions-item label="当前队列">{{ wechat.queueSize }}</el-descriptions-item></el-descriptions><el-alert v-if="wechat?.lastError" :title="wechat.lastError" type="error" :closable="false" /><div class="pc-actions"><el-button v-hasPermi="['paicli:connection:manage']" :loading="busy" :disabled="!directoryContextId" @click="setupWechatChannel">申请登录二维码</el-button><el-button v-if="wechat?.qrArtifactId" @click="showQr">查看当前二维码</el-button><el-button v-if="wechat" v-hasPermi="['paicli:connection:manage']" @click="openWechatBinding">绑定用户与 sender</el-button><el-button v-for="action in wechatActions" v-if="wechat" :key="action.value" v-hasPermi="['paicli:connection:manage']" :disabled="busy || !wechat.boundUserName" @click="actWechat(action.value)">{{ action.label }}</el-button></div><p class="pc-muted">start/status/pause/resume/stop/restart 只管理当前文本通道，控制命令与消息预算由中心裁决。</p></section><WechatPolicy v-if="wechat" :channel="wechat" :mcp-names="mcpServers.map(server=>server.name)" @saved="loadSettingsData" /></el-tab-pane>
      <el-tab-pane v-if="advanced" label="预算、策略与保留" name="policy"><section v-if="policy" class="pc-panel"><h2>我的策略版本 {{ policy.version }}</h2><el-alert title="确定性硬拒绝不能由配置或人工批准解除；当前命令执行必须使用已验证隔离环境。" type="warning" :closable="false" /><el-form label-width="180px"><el-form-item label="自动用户原话候选"><el-switch v-model="policy.autoFactExtractionEnabled" /></el-form-item><el-form-item label="自动上下文压缩"><el-switch v-model="policy.autoCompactionEnabled" /></el-form-item><el-form-item label="会话历史记忆辅助"><el-switch v-model="policy.sessionMemoryEnabled" /></el-form-item><el-form-item label="每用户活跃会话"><el-input-number v-model="policy.maxActiveSessions" :min="1" :max="10" /></el-form-item><el-form-item label="队列上限"><el-input-number v-model="policy.maxQueuedTasks" :min="1" :max="100" /></el-form-item><el-form-item label="只读工具并行数"><el-input-number v-model="policy.maxReadTools" :min="1" :max="4" /></el-form-item><el-form-item label="写任务并行数"><el-input-number v-model="policy.maxWriteTasks" :min="1" :max="1" /></el-form-item><el-form-item label="命令超时（秒）"><el-input-number v-model="policy.commandTimeoutSeconds" :min="1" :max="60" /></el-form-item><el-form-item label="审批超时（秒）"><el-input-number v-model="policy.approvalTimeoutSeconds" :min="60" :max="900" /></el-form-item><el-form-item label="每任务 Token 预算"><el-input-number v-model="policy.taskTokenBudget" :min="1" /></el-form-item><el-form-item label="每日 Token 预算"><el-input-number v-model="policy.dailyTokenBudget" :min="1" /></el-form-item><el-form-item label="数据保留（天）"><el-input-number v-model="policy.retentionDays" :min="1" /></el-form-item></el-form><h3>硬拒绝路径</h3><pre class="pc-pre">{{ policy.hardDeniedPaths.join('\n') }}</pre><h3>可申请能力</h3><pre class="pc-pre">{{ policy.allowedCapabilities.join('\n') }}</pre><el-button v-hasPermi="['paicli:connection:manage']" type="primary" :loading="busy" @click="savePersonalPolicy">保存策略版本</el-button></section><el-empty v-else description="个人策略不可用" /></el-tab-pane>
    </el-tabs>
    <el-dialog v-model="publishOpen" title="发布平台内置模型" width="650px"><p>发布 {{publishModel?.modelId}} 的固定版本。指定用户将通过中心使用管理员托管凭据，费用仍按中心预算记录；凭据不会展示给用户。</p><el-form label-width="130px"><el-form-item label="使用对象"><el-select v-model="publishAudience"><el-option label="所有已登录用户" value="AUTHENTICATED" /><el-option label="指定用户 ID" value="USERS" /></el-select></el-form-item><el-form-item v-if="publishAudience === 'USERS'" label="若依用户 ID"><el-input v-model="publishUsers" placeholder="多个稳定用户 ID 用逗号分隔" /></el-form-item><el-form-item label="平台默认模型"><el-checkbox v-model="publishDefault">供未设置个人默认模型的用户使用</el-checkbox></el-form-item></el-form><el-checkbox v-model="shareConfirmed">确认上述用户可以使用本模型及固定托管凭据</el-checkbox><template #footer><el-button @click="publishOpen=false">返回</el-button><el-button type="primary" :disabled="!shareConfirmed || !canPublish" :loading="busy" @click="publishRelease">确认发布</el-button></template></el-dialog>
    <el-dialog v-model="providerOpen" title="供应商受控配置" width="650px" class="pc-dialog"><el-form label-width="130px"><el-form-item label="供应商"><el-select v-model="providerForm.name" :disabled="!!providerForm.id"><el-option v-for="provider in providerNames" :key="provider" :label="provider === 'sub2api' ? 'Sub2API' : provider" :value="provider" /></el-select></el-form-item><el-form-item v-if="providerUsesSub2Api" label="调用 API" required><el-select v-model="providerForm.wireApi" placeholder="明确选择实例支持的 API"><el-option label="Responses" value="responses" /><el-option label="Chat Completions" value="chat_completions" /></el-select></el-form-item><el-form-item v-else label="协议">供应商原生协议适配</el-form-item><el-form-item label="地址"><el-input v-model="providerForm.baseUrl" :placeholder="providerUsesSub2Api ? 'HTTPS API 根地址，例如 https://sub2api.example/v1' : ''" /><p v-if="providerUsesSub2Api" class="pc-muted">{{ sub2EndpointPreview }}</p></el-form-item><el-form-item label="默认启动模型"><el-input v-model="providerForm.model" placeholder="完整模型 ID，不改变当前会话模型" /></el-form-item><el-form-item v-if="!providerUsesSub2Api" label="LoRA ID"><el-input v-model="providerForm.loraId" placeholder="原供应商适配支持的 LoRA ID" /></el-form-item><el-form-item v-hasPermi="['paicli:secret:write']" label="受控密钥引用"><el-input v-model="providerForm.secretRef" autocomplete="off" placeholder="引用已批准的密钥记录，不能输入 Key 正文" /></el-form-item></el-form><el-alert title="网页不保存或回显供应商 Key；只向中心提交受控引用，密钥管理需独立权限。" type="info" :closable="false" /><el-alert v-if="error" :title="error" type="error" :closable="false" /><template #footer><el-button @click="providerOpen = false">取消</el-button><el-button type="primary" :loading="busy" @click="saveProviderConfig">保存</el-button></template></el-dialog>
