const modelUsesSub2Api = computed(() => modelProvider.value?.provider === 'sub2api')
const sub2EndpointPreview = computed(() => `最终请求路径：${(providerForm.baseUrl || '').replace(/\/+$/, '')}/${providerForm.wireApi === 'responses' ? 'responses' : providerForm.wireApi === 'chat_completions' ? 'chat/completions' : '请选择调用 API'}`)
function wireApiName(wireApi?:PcProvider['wireApi']) { return wireApi === 'responses' ? 'Responses' : wireApi === 'chat_completions' ? 'Chat Completions' : '调用 API 未配置' }
let verifyingModel = false
async function verifyModel(model:PcModel,capability:'TEXT'|'IMAGES'='TEXT') {
  if (model.platformModel || verifyingModel || busy.value) return
  const provider = providers.value.find(item => item.id === model.providerId), owner = personal.context.value?.ownerUserId, generation = settingsGeneration
  if (!provider || provider.provider !== 'sub2api' || !provider.secretConfigured || !checkPermi(['paicli:connection:manage'])) { error.value='请先配置本人的 Sub2API 供应商和托管密钥';return }
  if (!provider.wireApi) { error.value='请选择 Sub2API 调用 API';return }
  if(capability==='IMAGES' && (provider.wireApi!=='responses' || !model.capabilityKnown)){error.value='图片验证需要已通过文字与工具验证的 Responses 模型';return}
  // 费用确认仅适用于当时看到的本人身份、供应商协议与模型版本。
  const frozenProvider = { ...provider }, frozenModel = { ...model }
  verifyingModel = true
  try {
    try { await ElMessageBox.confirm(`验证 ${frozenModel.modelId} 的 ${wireApiName(frozenProvider.wireApi)} ${capability==='IMAGES' ? '图片观察及工具回灌' : '文字及工具'}：最多发送两次合成模型请求，每次最多 256 输出 Token，按中心预算记账；不执行业务工具。`,'确认模型兼容验证',{type:'warning',confirmButtonText:'确认并发起',cancelButtonText:'取消'}) }
    catch { return }
    const currentProvider = providers.value.find(item => item.id === frozenProvider.id), currentModel = models.value.find(item => item.id === frozenModel.id)
    if (owner !== personal.context.value?.ownerUserId || generation !== settingsGeneration || !checkPermi(['paicli:connection:manage']) || !currentProvider?.secretConfigured || currentProvider.version !== frozenProvider.version || currentProvider.wireApi !== frozenProvider.wireApi || currentModel?.version !== frozenModel.version || currentModel.providerId !== frozenProvider.id) {
      error.value='本人身份、权限或配置版本已变化，请刷新配置后重新确认验证';return
    }
    const intent={ownerUserId:owner,providerId:frozenProvider.id,providerVersion:frozenProvider.version,modelId:frozenModel.id,modelVersion:frozenModel.version,action:'verify',capability}
    await run(async () => {
      const response = await verifyProviderModel(frozenProvider,frozenModel,keys.get(intent),capability);keys.done(intent)
      if (owner !== personal.context.value?.ownerUserId || generation !== settingsGeneration || !checkPermi(['paicli:connection:manage']) || models.value.find(item=>item.id===frozenModel.id)?.version!==frozenModel.version) return
      trackTask(response.data,capability==='IMAGES' ? 'Sub2API 图片理解验证' : 'Sub2API 文字与工具验证');await reload()
    })
  } finally { verifyingModel = false }
}
function editProvider(provider?: PcProvider) { for (const key of Object.keys(providerForm)) delete (providerForm as Record<string,unknown>)[key]; Object.assign(providerForm,provider ?? { name:'',protocol:'NATIVE',baseUrl:'',secretRef:'',version:0 }); providerOpen.value = true; error.value = '' }
async function saveProviderConfig() { if (providerUsesSub2Api.value && !providerForm.wireApi) { error.value = '请选择 Sub2API 调用 API'; return }; const data = { ...providerForm,wireApi:providerUsesSub2Api.value ? providerForm.wireApi : undefined,model:providerForm.model?.trim() || undefined,loraId:providerUsesSub2Api.value ? undefined : providerForm.loraId?.trim() || undefined }; await run(async () => { await saveProvider(data,keys.get(data)); keys.done(data); providerOpen.value = false; await reload() }) }
async function refreshProvider(provider: PcProvider) { const intent = { action:'refresh',id:provider.id,version:provider.version }; await run(async () => { trackTask((await refreshModels(provider.id,provider.version,keys.get(intent))).data,'刷新供应商模型'); keys.done(intent); await reload() }) }
function applyModelTemplate() { const template = models.value.find(model => model.id === templateModelId.value && model.providerId === modelForm.providerId); Object.assign(modelForm,modelTemplateFields(template)) }
function editModel(model?: PcModel) { if(model?.platformModel)return; for(const field of Object.keys(modelForm))delete(modelForm as Record<string,unknown>)[field]; Object.assign(modelForm,model ? {...model} : {providerId:providers.value[0]?.id || '',modelId:'',contextWindow:128000,supportsImages:false,supportsThinking:false,supportsTools:false,capabilityKnown:false,enabled:true}); templateModelId.value='';modelOpen.value=true;error.value='' }
function trackTask(data: PcTask | PcMcpServer | PcWechat, title: string) { if('mode' in data && data.mode==='CONTROL'){operationTaskId.value=data.id;operationTitle.value=title} }
async function operationSettled(task: PcTaskDetail) { if((task.directoryContextId ?? '') === directoryContextId.value)await reload() }
async function actBrowser(action:'TABS'|'CONNECT'|'DISCONNECT') { const current=browser.value;if(!current?.id)return;const intent={id:current.id,version:current.version,action};await run(async()=>{trackTask((await browserAction(intent.id,intent.version,action,keys.get(intent))).data,`浏览器 ${action}`);keys.done(intent)}) }
function isPromptDefinition(prompt: unknown): prompt is PcMcpPromptDefinition {
  if (!prompt || typeof prompt !== 'object' || !('name' in prompt) || typeof prompt.name !== 'string' || !prompt.name.trim()) return false
  if (!('arguments' in prompt) || prompt.arguments === undefined) return true
  return Array.isArray(prompt.arguments) && prompt.arguments.every(argument => argument && typeof argument === 'object' && typeof argument.name === 'string' && argument.name.trim() && (argument.required === undefined || typeof argument.required === 'boolean'))
}
function hasPromptReference(reference: string) { return selectedMcp.value?.prompts.some(prompt => isPromptDefinition(prompt) && prompt.name === reference) === true }
async function requestMcp(kind:'resource'|'prompt',reference:string,args?:Record<string,string>) { const server=selectedMcp.value;if(!server || typeof reference!=='string' || !reference.trim() || (kind==='prompt'&&!hasPromptReference(reference)))return;mcpContent.value=undefined;const data={kind,reference,arguments:args},intent={id:server.id,version:server.version,...data};await run(async()=>{trackTask((await requestMcpContent(server.id,server.version,data,keys.get(intent))).data,`MCP ${kind==='resource'?'资源':'提示词'}读取`);keys.done(intent);promptOpen.value=false}) }
function openPrompt(prompt: PcMcpPrompt) { if(!isPromptDefinition(prompt))return;selectedPrompt.value=prompt;for(const key of Object.keys(promptArguments))delete promptArguments[key];for(const argument of prompt.arguments || [])promptArguments[argument.name]='';promptOpen.value=true }
async function submitPrompt(){const prompt=selectedPrompt.value;if(!prompt||prompt.arguments?.some(item=>item.required&&!promptArguments[item.name]?.trim()))return;await requestMcp('prompt',prompt.name,{...promptArguments})}
async function saveModel() { if(models.value.find(item=>item.id === modelForm.id)?.platformModel || !checkPermi(['paicli:connection:manage']))return; const data = { ...modelForm,thinking:modelForm.thinking || null,reasoningEffort:modelForm.reasoningEffort || null,reasoningHistory:typeof modelForm.reasoningHistory==='boolean'?modelForm.reasoningHistory:null,dsml:typeof modelForm.dsml==='boolean'?modelForm.dsml:null,supportsThinking:modelForm.thinking ? modelForm.thinking === 'enabled' : modelForm.supportsThinking }; for(const field of ['verification','imageVerification','imageVerificationFailure','configurationVersion','imageInput','releaseId','releaseVersion','releaseCasVersion','releaseStatus','platformModel'])delete (data as Record<string,unknown>)[field]; if(modelUsesSub2Api.value){data.supportsImages=false;data.capabilityKnown=false}; await run(async () => { await addModel(data,keys.get(data)); keys.done(data); modelOpen.value = false; modelForm.modelId = ''; await reload() }) }
function editMcp(server?: PcMcpServer) { for (const key of Object.keys(mcpForm)) delete (mcpForm as Record<string,unknown>)[key]; Object.assign(mcpForm,server ? { ...server } : { name:'',scope:'PROJECT',transport:'STDIO',version:0 }); mcpArgs.value = JSON.stringify(server?.args ?? []); mcpEnvRefs.value = JSON.stringify(server?.envSecretRefs ?? {},null,2); mcpHeaderRefs.value = JSON.stringify(server?.headerSecretRefs ?? {},null,2); mcpPublicHeaders.value = JSON.stringify(server?.headers ?? {},null,2); mcpFormError.value = ''; error.value = ''; mcpOpen.value = true }
async function saveMcpConfig() {
  let args: string[] = [], envSecretRefs: Record<string,string> = {}, headerSecretRefs: Record<string,string> = {}, headers: Record<string,string> = {}
  try {
    if (mcpForm.transport === 'STDIO') { const parsed: unknown = JSON.parse(mcpArgs.value); if (!Array.isArray(parsed) || parsed.some(item => typeof item !== 'string')) throw new Error('参数必须是 JSON 字符串数组'); args = parsed; envSecretRefs = parseMcpReferences(mcpEnvRefs.value,personal.context.value?.ownerUserId ?? '','STDIO') }
    else { headerSecretRefs = parseMcpReferences(mcpHeaderRefs.value,personal.context.value?.ownerUserId ?? '','HTTP'); headers = parseMcpPublicHeaders(mcpPublicHeaders.value) }
  } catch(cause) { mcpFormError.value = errorText(cause); return }
  mcpFormError.value = ''
  const data: Partial<PcMcpServer> = { id:mcpForm.id,version:mcpForm.version,name:mcpForm.name,scope:mcpForm.scope,transport:mcpForm.transport,command:mcpForm.transport === 'STDIO' ? mcpForm.command : undefined,args,url:mcpForm.transport === 'HTTP' ? mcpForm.url : undefined,envSecretRefs,headerSecretRefs,headers }, intent = { directoryContextId:directoryContextId.value,...data }
  await run(async () => { await saveMcp(directoryContextId.value,data,keys.get(intent)); keys.done(intent); mcpOpen.value = false; await loadSettingsData() })
}
function viewMcp(server: PcMcpServer) { selectedMcp.value = server; mcpContent.value = undefined; mcpLog.value = []; mcpDetailOpen.value = true }
async function actMcp(server: PcMcpServer,action: 'START'|'STOP'|'RESTART'|'TRUST') { if (action === 'TRUST') { try { await ElMessageBox.confirm(`信任 ${server.name} 本次配置哈希 ${server.configHash}。stdio 执行代码仍须隔离和操作批准，确认已核对来源？`,'信任当前 MCP 配置',{ type:'warning' }) } catch { return } }; const intent = { id:server.id,action,version:server.version,configHash:server.configHash }; await run(async () => { trackTask((await mcpAction(server.id,action,server.version,server.configHash,keys.get(intent))).data,`MCP ${server.name} ${action}`); keys.done(intent); await loadSettingsData(); selectedMcp.value = mcpServers.value.find(item => item.id === server.id) }) }
async function mcpLogs(server: PcMcpServer) { viewMcp(server); await run(async () => { mcpLog.value = (await getMcpLogs(server.id)).data }) }
async function readMcp(kind: 'resource'|'prompt',reference: string) { const id = selectedMcp.value?.id; if (!id || typeof reference!=='string' || !reference.trim() || (kind==='prompt'&&!hasPromptReference(reference))) return; await run(async () => { const response = await getMcpContent(id,kind,reference); if (id === selectedMcp.value?.id) mcpContent.value = response.data }) }
async function probe() { const id = directoryContextId.value,intent = { action:'probe',id }; await run(async () => { const response = await probeBrowser(id,keys.get(intent)); keys.done(intent); trackTask(response.data,'浏览器探活'); if (id === directoryContextId.value) await loadSettingsData() }) }
async function saveBrowser() { if (!browser.value) return; const data = { ...browserForm,directoryContextId:directoryContextId.value,version:browser.value.version }; await run(async () => { await updateBrowser(data,keys.get(data)); keys.done(data); await loadSettingsData() }) }
async function showSkill(id: string) { await run(async () => { selectedSkill.value = (await getSkill(id)).data; skillOpen.value = true }) }
async function toggleSkill(skill: PcSkill) { const intent = { id:skill.id,version:skill.version,enabled:!skill.enabled }; await run(async () => { trackTask((await setSkillEnabled(skill.id,!skill.enabled,skill.version,keys.get(intent))).data,`Skill ${skill.name} 配置生效`); keys.done(intent); await loadSettingsData() }) }
async function reloadSkillList() { const id = directoryContextId.value,intent = { action:'reload-skills',id }; await run(async () => { trackTask((await reloadSkills(id,keys.get(intent))).data,'重载 Skills'); keys.done(intent); await loadSettingsData() }) }
async function setupWechatChannel() { const id = directoryContextId.value,intent = { action:'wechat-setup',id }; await run(async () => { wechat.value = (await setupWechat(id,keys.get(intent))).data; if(wechat.value?.taskId){operationTaskId.value=wechat.value.taskId;operationTitle.value='微信登录二维码'}; keys.done(intent) }) }
function openWechatBinding(){wechatBinding.modelId=wechat.value?.modelId || '';wechatBinding.dailyBudget=wechat.value?.dailyBudget || 100000;wechatBindingOpen.value=true}
async function bindWechatIdentity() { const channel = wechat.value; if (!channel) return; const data = { ...wechatBinding,modelId:wechatBinding.modelId || undefined,directoryContextId:directoryContextId.value,version:channel.version },intent = { id:channel.id,...data }; await run(async () => { await bindWechat(channel.id,data,keys.get(intent)); keys.done(intent); wechatBindingOpen.value = false; wechatBinding.sender = ''; await loadSettingsData() }) }
async function actWechat(action: 'START'|'PAUSE'|'RESUME'|'STOP'|'RESTART') { const channel = wechat.value; if (!channel) return; const intent = { id:channel.id,version:channel.version,action }; await run(async () => { trackTask((await wechatAction(channel.id,action,channel.version,keys.get(intent))).data,`微信通道 ${action}`); keys.done(intent); await loadSettingsData() }) }
function clearQr() { if (qrUrl.value) URL.revokeObjectURL(qrUrl.value); qrUrl.value = '' }
async function showQr() { const id = wechat.value?.qrArtifactId; if (!id) return; await run(async () => { const blob = await downloadArtifact(id); if (!['image/png','image/jpeg'].includes(blob.type)) throw new Error('二维码内容不是支持的图片'); clearQr(); qrUrl.value = URL.createObjectURL(blob); qrOpen.value = true }) }
async function savePersonalPolicy() { const data = policy.value; if (!data) return; const intent = { ownerUserId:personal.context.value?.ownerUserId,...data }; await run(async () => { await savePolicy(undefined,{ ...data },keys.get(intent)); keys.done(intent); await loadSettingsData() }) }
watch(advanced, enabled=>{if(enabled)void loadSettingsData();else tab.value='models'})
watch(directoryContextId, () => { settingsGeneration++; wechatBindingOpen.value=false; operationTaskId.value='';promptOpen.value=false; mcpOpen.value = false; clearQr(); qrOpen.value = false; selectedMcp.value = undefined; providers.value = []; models.value = []; mcpServers.value = []; browser.value = undefined; skills.value = []; wechat.value = undefined; policy.value = undefined; void loadSettingsData() }); watch(() => modelForm.providerId,()=>{if(!modelForm.id)applyModelTemplate()})
onMounted(reload); onBeforeUnmount(() => { settingsGeneration++; providerGeneration++; clearQr() })
</script>
<style scoped>.pc-panel + .pc-panel{margin-top:16px}.pc-mcp-prompt{overflow-wrap:anywhere}</style>
